return ['project-id-version'=>'Lingua Forge 2.1.0','report-msgid-bugs-to'=>'https://wordpress.org/support/plugin/lingua-forge','last-translator'=>'admin','language-team'=>'Arabic','mime-version'=>'1.0','content-type'=>'text/plain; charset=UTF-8','content-transfer-encoding'=>'8bit','pot-creation-date'=>'2026-06-01T15:14:22+00:00','po-revision-date'=>'2026-06-01 17:28+0000','x-generator'=>'Loco https://localise.biz/','x-domain'=>'lingua-forge','language'=>'ar','plural-forms'=>'nplurals=6; plural=n==0 ? 0 : n==1 ? 1 : n==2 ? 2 : n%100 >= 3 && n%100<=10 ? 3 : n%100 >= 11 && n%100<=99 ? 4 : 5;','x-loco-version'=>'2.8.5; wp-7.0; php-8.3.31','messages'=>['Lingua Forge'=>'لينجوا فورج','https://github.com/leotiger/lingua-forge'=>'https://github.com/leotiger/lingua-forge','Multilingual routing, SEO meta tags, and AI content tools for WordPress. Combines language detection, URL routing, hreflang, meta descriptions, and AI-powered excerpt, meta, and translation features.'=>'التوجيه متعدد اللغات، علامات وصف SEO، وأدوات المحتوى بالذكاء الاصطناعي لووردبريس. يجمع بين اكتشاف اللغة، توجيه URL، hreflang، أوصاف الميتا، وميزات المقتطفات، الميتا، والترجمة المدعومة بالذكاء الاصطناعي.','Uli Hake'=>'ولي هاك','https://lingua-forge.com'=>'https://lingua-forge.com','Translate'=>'ترجمة','Lingua Forge — Quick Translate'=>'لينجوا فورج — الترجمة السريعة','Informative'=>'معلوماتي','Persuasive'=>'إقناعي','Storytelling'=>'سرد القصص','Technical'=>'تقني','Conversational'=>'محادثة','Permission denied.'=>'تم رفض الإذن.','Cannot determine target language from slug.'=>'لا يمكن تحديد اللغة الهدف من الرابط المختصر.','Invalid post type.'=>'نوع المنشور غير صالح.','Invalid or primary language.'=>'اللغة غير صالحة أو أساسية.','Template not found or not stored in the database.'=>'القالب غير موجود أو غير مخزن في قاعدة البيانات.','Template has no content.'=>'القالب لا يحتوي على محتوى.','No internal links found to update.'=>'لم يتم العثور على روابط داخلية للتحديث.','%d link updated.'=>'تم تحديث %d رابط.' . "\0" . 'تم تحديث %d روابط.' . "\0" . '' . "\0" . '' . "\0" . '' . "\0" . '','No language-specific template parts found to map.'=>'لم يتم العثور على أجزاء قالب محددة للغة لتعيينها.','No template part references needed updating.'=>'لا حاجة لتحديث مراجع أجزاء القالب.','%d part reference updated.'=>'تم تحديث مرجع جزء %d.' . "\0" . 'تم تحديث مراجع الأجزاء %d.' . "\0" . '' . "\0" . '' . "\0" . '' . "\0" . '','Invalid language.'=>'اللغة غير صالحة.','Template part not found or not stored in the database.'=>'جزء القالب غير موجود أو غير مخزن في قاعدة البيانات.','Template part has no content.'=>'جزء القالب لا يحتوي على محتوى.','No navigation references needed updating.'=>'لا حاجة لتحديث مراجع التنقل.','%d navigation reference updated.'=>'تم تحديث مرجع تنقل %d.' . "\0" . 'تم تحديث مراجع التنقل %d.' . "\0" . '' . "\0" . '' . "\0" . '' . "\0" . '','No AI provider configured.'=>'مزود الذكاء الاصطناعي غير مهيأ.','Missing pattern name or language.'=>'اسم النمط أو اللغة مفقود.','Pattern not found.'=>'لم يتم العثور على النمط.','Pattern has no content to translate.'=>'النمط لا يحتوي على محتوى للترجمة.','AI provider returned an empty response.'=>'استجابة فارغة من مزود الذكاء الاصطناعي.','Pattern translated and saved. Copy the content into your CPT post via the block editor Pattern inserter or use it as a starting point for a Reusable Block.'=>'تم ترجمة النمط وحفظه. انسخ المحتوى إلى منشور CPT الخاص بك عبر أداة إدراج الأنماط في محرر الكتل أو استخدمه كنقطة انطلاق لكتلة قابلة لإعادة الاستخدام.','Invalid template type.'=>'نوع القالب غير صالح.','Template "%s" already exists.'=>'القالب "%s" موجود بالفعل.','"%s" created.'=>'تم إنشاء "%s".','Invalid template part.'=>'جزء القالب غير صالح.','Template part "%s" already exists.'=>'جزء القالب "%s" موجود بالفعل.','"%1$s" created. %2$d template updated.'=>'تم إنشاء "%1$s". تم تحديث %2$d قالب.' . "\0" . 'تم إنشاء "%1$s". تم تحديث %2$d قوالب.' . "\0" . '' . "\0" . '' . "\0" . '' . "\0" . '','Page'=>'صفحة','Single'=>'مفرد','Search'=>'بحث','Search Results'=>'نتائج البحث','Archive'=>'أرشيف','Front Page'=>'الصفحة الرئيسية','Single: %s'=>'فرد: %s','Single %s'=>'فرد %s','Archive: %s'=>'الأرشيف: %s','%s Archive'=>'%s الأرشيف','No source content found to translate.'=>'لم يتم العثور على محتوى مصدر لترجمته.','Translated. Review in the Site Editor — internal links, navigation URLs, and template slugs are not updated automatically.'=>'تمت الترجمة. راجع في محرر الموقع — الروابط الداخلية، روابط التنقل، واسم القوالب لا يتم تحديثها تلقائيًا.','Navigation not found.'=>'لم يتم العثور على التنقل.','Navigation has no content to translate.'=>'لا يوجد محتوى للتنقل لترجمته.','"%1$s %2$s" saved.'=>'تم حفظ "%1$s %2$s".','Translate page…'=>'ترجمة الصفحة…','Generate content…'=>'إنشاء المحتوى…','AI Behaviour Preset'=>'إعداد سلوك الذكاء الاصطناعي','Custom'=>'مخصص','Global default (%s)'=>'الإعداد الافتراضي العالمي (%s)','Overrides the AI preset for Translation and Content Generation on this page. Site-wide custom prompt instructions (Settings → Behavior) are always appended to every request regardless of this selection.'=>'يتجاوز إعداد الذكاء الاصطناعي للترجمة وتوليد المحتوى في هذه الصفحة. دائمًا ما يتم إلحاق تعليمات الموجه المخصصة على مستوى الموقع (الإعدادات → السلوك) بكل طلب بغض النظر عن هذا الاختيار.','Overrides the AI preset for Translation and Content Generation on this page. All other features always use the global preset.'=>'يتجاوز إعداد الذكاء الاصطناعي للترجمة وتوليد المحتوى في هذه الصفحة. تستخدم جميع الميزات الأخرى دائمًا الإعداد الافتراضي العالمي.','Close'=>'إغلاق','Translate missing'=>'الترجمة المفقودة','From'=>'من','Retranslate'=>'إعادة الترجمة','Translating…'=>'جارٍ الترجمة…','Retranslating…'=>'جارٍ إعادة الترجمة…','✓ Done'=>'✓ تم','Error'=>'خطأ','Navigation posts are translated via the Router tab, not this button.'=>'يتم ترجمة منشورات التنقل عبر علامة التبويب Router، وليس هذا الزر.','Creating translations for post type "%s" requires an active integration. Please ensure the required integration is installed and active.'=>'إنشاء ترجمات لنوع المنشور "%s" يتطلب تكامل نشط. يرجى التأكد من تثبيت وتفعيل التكامل المطلوب.','No %s version found in this translation group.'=>'لم يتم العثور على إصدار %s في مجموعة الترجمات هذه.','AI Usage'=>'استخدام الذكاء الاصطناعي','Today'=>'اليوم','Last 7 days'=>'آخر 7 أيام','Last 30 days'=>'آخر 30 يومًا','All time'=>'جميع الأوقات','Token consumption rolled up by feature, provider, and model. Recorded on every successful AI call; Test Connection pings are deliberately excluded so they don\'t skew the totals. The underlying table aggregates daily — pick a window below to view it.'=>'استهلاك الرموز مجمع حسب الميزة، المزود، والنموذج. مسجل في كل مكالمة ذكاء اصطناعي ناجحة؛ يتم استبعاد اختبار الاتصال عمدًا حتى لا تؤثر على الإجماليات. الجدول الأساسي يجمع البيانات يوميًا — اختر نافذة أدناه لعرضها.','No AI usage recorded yet. Once an editor runs a translation, generates a meta description, or uses any other AI feature, totals will appear here.'=>'لم يتم تسجيل استخدام للذكاء الاصطناعي بعد. بمجرد أن يقوم محرر بتشغيل ترجمة، أو إنشاء وصف ميتا، أو استخدام أي ميزة أخرى للذكاء الاصطناعي، ستظهر الإجماليات هنا.','No AI usage recorded in the selected window (%s). Pick a wider range above.'=>'لم يتم تسجيل استخدام للذكاء الاصطناعي في النافذة المختارة (%s). اختر نطاقًا أوسع أعلاه.','Feature'=>'الميزة','Provider'=>'المزود','Model'=>'النموذج','Requests'=>'الطلبات','Input tokens'=>'رموز الإدخال','Output tokens'=>'رموز الإخراج','Total tokens'=>'إجمالي الرموز','Total'=>'الإجمالي','API Keys'=>'مفاتيح API','Keys are encrypted with AES-256-CBC before being stored in the WordPress database. The encryption secret is derived from your WordPress auth salts (wp-config.php), so plaintext keys never touch the database.'=>'يتم تشفير المفاتيح باستخدام AES-256-CBC قبل تخزينها في قاعدة بيانات ووردبريس. يتم اشتقاق سر التشفير من ملح المصادقة الخاص بك في ووردبريس (wp-config.php)، لذلك المفاتيح النصية العادية لا تلمس قاعدة البيانات.','API Key'=>'مفتاح API','Paste your API key…'=>'الصق مفتاح API الخاص بك…','✓ Configured'=>'✓ تم التكوين','✗ Not configured'=>'✗ غير مكون','Test connection'=>'اختبار الاتصال','Leave blank to keep the existing key. Enter a new value to replace it.'=>'اتركه فارغًا للحفاظ على المفتاح الحالي. أدخل قيمة جديدة لاستبداله.','Remove stored key'=>'إزالة المفتاح المخزن','This key is currently supplied by a server %s and cannot be removed here. Enter a new key above to override it with a database value.'=>'هذا المفتاح يتم تزويده حاليًا من قبل خادم %s ولا يمكن إزالته هنا. أدخل مفتاحًا جديدًا أعلاه لتجاوز ذلك بقيمة من قاعدة البيانات.','environment variable'=>'متغير البيئة','PHP constant'=>'ثابت PHP','Alternative (server-side):'=>'بديل (جانب الخادم):','You can also define keys as constants or environment variables (e.g. in wp-config.php). Those sources are used automatically as a fallback when no database key is stored.'=>'يمكنك أيضًا تعريف المفاتيح كثوابت أو متغيرات بيئة (على سبيل المثال في wp-config.php). تُستخدم هذه المصادر تلقائيًا كبديل عند عدم وجود مفتاح مخزن في قاعدة البيانات.','To use a custom encryption secret (instead of the derived wp_salt value), add this to wp-config.php:'=>'لاستخدام سر تشفير مخصص (بدلاً من قيمة wp_salt المستمدة)، أضف هذا إلى wp-config.php:','Unknown provider.'=>'مزود غير معروف.','No API key configured for this provider.'=>'لا يوجد مفتاح API مهيأ لهذا المزود.','Could not instantiate the provider.'=>'تعذر إنشاء المزود.','Provider returned no text. Check the WordPress error log for the detailed failure reason.'=>'لم يُرجع المزود نصًا. تحقق من سجل أخطاء ووردبريس لمعرفة سبب الفشل بالتفصيل.','Behavior'=>'السلوك','Block Editor'=>'محرر الكتلة','Lingua Forge restricts two Gutenberg features by default to keep editorial behavior consistent across languages. Opt in here when you need full Gutenberg / FSE capabilities.'=>'يقيد Lingua Forge ميزتين من Gutenberg بشكل افتراضي للحفاظ على اتساق السلوك التحريري عبر اللغات. اختر هنا عندما تحتاج إلى قدرات كاملة لـ Gutenberg / FSE.','Block locking'=>'قفل الكتلة','Allow editors to lock individual blocks'=>'السماح للمحررين بقفل الكتل الفردية','Re-enables Gutenberg\'s canLockBlocks. Useful for editorial templates that need to prevent contributors from moving or deleting specific blocks.'=>'يعيد تفعيل canLockBlocks الخاص بـ Gutenberg. مفيد لنماذج التحرير التي تحتاج إلى منع المساهمين من نقل أو حذف كتل معينة.','Template mode'=>'وضع النموذج','Allow Gutenberg template-editing mode on post screens'=>'السماح بوضع تحرير النموذج في صفحات المنشور','Re-enables supportsTemplateMode. Core to Full-Site-Editing workflows where post-level template overrides are intentional.'=>'يعيد تفعيل supportsTemplateMode. أساسي لعمليات تحرير الموقع الكامل حيث تكون تجاوزات النموذج على مستوى المنشور مقصودة.','Compliance Preset'=>'إعدادات الامتثال','Strict-preservation mode for legal, regulatory, medical, or technical content. When on, every AI feature uses a low sampling temperature and appends the addendum below to its system prompt — terminology, article numbers, units, brand names, and regulatory language are preserved verbatim rather than paraphrased.'=>'وضع الحفظ الصارم للمحتوى القانوني والتنظيمي والطبي أو التقني. عند التفعيل، يستخدم كل ميزة ذكاء اصطناعي درجة حرارة عينة منخفضة ويضيف الملحق أدناه إلى مطالبه النظامية — يتم الحفاظ على المصطلحات وأرقام المقالات والوحدات وأسماء العلامات التجارية واللغة التنظيمية حرفيًا بدلاً من إعادة صياغتها.','Global AI preset'=>'إعدادات الذكاء الاصطناعي العالمية','T=%s'=>'T=%s','T=0.2–0.6, per feature'=>'T=0.2–0.6، لكل ميزة','Sets the default AI behaviour for all features site-wide. Individual posts can override this for Translation and Content Generation via the Lingua Forge meta box.'=>'يحدد السلوك الافتراضي للذكاء الاصطناعي لجميع الميزات على مستوى الموقع. يمكن للمنشورات الفردية تجاوز ذلك لخاصية الترجمة وتوليد المحتوى عبر مربع بيانات Lingua Forge.','Standard uses each feature\'s own tuned temperature: Translation T=0.2 (precise), Quick Translate T=0.4, Content Generator T=0.6 (creative). The other presets apply a single fixed temperature across all features.'=>'يستخدم الوضع القياسي درجة حرارة مخصصة لكل ميزة: الترجمة T=0.2 (دقيق)، الترجمة السريعة T=0.4، مولد المحتوى T=0.6 (مبدع). تطبق الإعدادات المسبقة الأخرى درجة حرارة ثابتة واحدة عبر جميع الميزات.','Technical / Scientific instructions'=>'تعليمات تقنية / علمية','Legal / Compliance instructions'=>'تعليمات قانونية / امتثال','Creative / Marketing instructions'=>'تعليمات إبداعية / تسويقية','Leave blank to use the built-in default. Clearing a saved override restores the default on next save.'=>'اتركه فارغًا لاستخدام الإعداد الافتراضي المدمج. استعادة تجاوز محفوظ يعيد التعيين إلى الافتراضي عند الحفظ التالي.','View built-in default'=>'عرض الإعداد الافتراضي المدمج','Translation Memory'=>'ذاكرة الترجمة','Cache translated equivalents at the block level so reusable content (shared footers, sidebars, accordions, boilerplate-heavy legal sections) does not pay an API call every time. When enabled, the translation flow parses each post into blocks, looks each block up in the cache, and sends only uncached blocks to the AI in a single batched request. Glossary edits and Compliance preset changes automatically invalidate affected cached translations. View statistics and clear the cache under Maintenance.'=>'تخزين الترجمات المترجمة على مستوى الكتلة بحيث لا يدفع المحتوى القابل لإعادة الاستخدام (التذييلات المشتركة، الشريط الجانبي، الأكورديونات، الأقسام القانونية الثقيلة) مكالمة API في كل مرة. عند التفعيل، يقوم تدفق الترجمة بتحليل كل منشور إلى كتل، ويبحث في ذاكرة التخزين المؤقت عن كل كتلة، ويرسل فقط الكتل غير المخزنة إلى الذكاء الاصطناعي في طلب مجمع واحد. تعديلات القاموس وتغييرات إعدادات الامتثال تلغي تلقائيًا صلاحية الترجمات المخزنة المؤقتًا المتأثرة. عرض الإحصائيات ومسح ذاكرة التخزين المؤقت تحت الصيانة.','Enable block-level translation cache reuse across posts'=>'تمكين إعادة استخدام ذاكرة التخزين المؤقت للترجمة على مستوى الكتلة عبر المنشورات','Currently skipped for posts that use block-comment attribute placeholders (wp:details summary fields, etc.) — they fall through to the existing single-call translation path.'=>'حاليًا يتم تخطيها للمنشورات التي تستخدم عناصر نائب عن طريق تعليق الكتلة (حقول wp:details الملخص، إلخ) — فهي تمر إلى مسار الترجمة ذو الطلب الواحد الموجود.','General'=>'عام','Light'=>'خفيف','Meta Description, Excerpt Generator'=>'وصف ميتا، مولد المقتطفات','Quality'=>'جودة','Translation, Content Generator'=>'الترجمة، مولد المحتوى','Active Provider'=>'مزود نشط','Currently inherited from the %s constant. Selecting a value here will override it.'=>'موروث حاليًا من الثابت %s. اختيار قيمة هنا سيقوم بتجاوزها.','Models'=>'نماذج','Features are grouped into two tiers. Enter the exact model identifier for each tier and provider. Leave a field blank to use the built-in default (shown as placeholder). Only the active provider\'s models are called at runtime — configure the others in advance if you plan to switch.'=>'يتم تصنيف الميزات إلى مستويين. أدخل معرف النموذج الدقيق لكل مستوى ومزود. اترك حقلًا فارغًا لاستخدام الإعداد الافتراضي المدمج (المعروض كعنصر نائب). يتم استدعاء نماذج المزود النشط فقط عند التشغيل — قم بتكوين الآخرين مسبقًا إذا كنت تخطط للتبديل.','active'=>'نشط','overridden'=>'تم تجاوزها','Tip: to reset a model to the built-in default, clear the field and save.'=>'نصيحة: لإعادة تعيين نموذج إلى الإعداد الافتراضي المدمج، امسح الحقل واحفظ.','Glossary'=>'القاموس','User-managed terminology table per language pair. Entries are appended to the translation system prompt so the AI uses preferred terms consistently — critical for domain vocabulary ("kWp", "PPA", "interconnection point"), brand names that must not translate, and standardised regulatory phrasing. Both language fields are optional: leave "Source language" blank to apply the entry regardless of which language you are translating from; leave "Target language" blank to apply it to all target languages at once.'=>'جدول المصطلحات الذي يديره المستخدم لكل زوج لغة. يتم إرفاق الإدخالات بموجه نظام الترجمة بحيث يستخدم الذكاء الاصطناعي المصطلحات المفضلة بشكل متسق — وهو أمر حاسم لمفردات المجال ("kWp"، "PPA"، "نقطة الاتصال")، أسماء العلامات التجارية التي لا يجب ترجمتها، والعبارات التنظيمية الموحدة. كلا حقلَي اللغة اختياريان: اترك "اللغة المصدر" فارغة لتطبيق الإدخال بغض النظر عن اللغة التي تترجم منها؛ اترك "اللغة الهدف" فارغة لتطبيقه على جميع اللغات الهدف مرة واحدة.','Glossary entry added.'=>'تمت إضافة إدخال المصطلح.','Glossary entry removed.'=>'تمت إزالة إدخال المصطلح.','Could not add entry: source term and target term are required.'=>'تعذر إضافة الإدخال: يتطلب الأمر المصطلح المصدر والمصطلح الهدف.','Could not save the glossary entry.'=>'تعذر حفظ إدخال المصطلح.','Source language'=>'اللغة المصدر','— Any —'=>'— أي —','Target language'=>'اللغة الهدف','— Any target —'=>'— أي هدف —','Filter'=>'تصفية','Reset'=>'إعادة تعيين','No glossary entries match the current filter. Clear the filter to see all entries, or add a new entry below.'=>'لا تتطابق إدخالات المصطلح مع التصفية الحالية. قم بمسح التصفية لرؤية جميع الإدخالات، أو أضف إدخالًا جديدًا أدناه.','No glossary entries yet. Add one below to start enforcing terminology in translations.'=>'لا توجد إدخالات مصطلح بعد. أضف واحدًا أدناه لبدء تطبيق المصطلحات في الترجمات.','Source term'=>'المصطلح المصدر','Target term'=>'المصطلح الهدف','Source lang'=>'اللغة المصدر','Target lang'=>'اللغة الهدف','Notes'=>'ملاحظات','any'=>'أي','Delete this glossary entry?'=>'هل تريد حذف إدخال المصطلح هذا؟','Delete'=>'حذف','Add new entry'=>'إضافة إدخال جديد','The phrase as it appears in the source text.'=>'العبارة كما تظهر في النص المصدر.','How it should appear in the translation. Type the same value as the source term to instruct the AI to preserve it verbatim.'=>'كيف يجب أن تظهر في الترجمة. اكتب نفس قيمة المصطلح المصدر لتوجيه الذكاء الاصطناعي للحفاظ عليه حرفيًا.','— Any source language —'=>'— أي لغة مصدر —','Leave blank for brand names and language-agnostic terms that should be enforced regardless of which language we are translating from.'=>'اتركه فارغًا لأسماء العلامات التجارية والمصطلحات غير المرتبطة باللغة والتي يجب تطبيقها بغض النظر عن اللغة التي نترجم منها.','— Any target language —'=>'— أي لغة هدف —','Leave blank to apply this entry to all target languages — ideal for brand names, abbreviations, and terms that must be preserved verbatim in every translation.'=>'اتركه فارغًا لتطبيق هذا الإدخال على جميع اللغات الهدف — مثالي لأسماء العلامات التجارية، الاختصارات، والمصطلحات التي يجب أن تُحفظ حرفيًا في كل ترجمة.','Optional context for editors (e.g. "ASIC = Application-Specific Integrated Circuit; preserve in English in technical contexts").'=>'السياق الاختياري للمحررين (مثل "ASIC = الدائرة المتكاملة الخاصة بالتطبيق؛ الحفاظ عليها باللغة الإنجليزية في السياقات التقنية").','Add entry'=>'إضافة إدخال','Limits'=>'الحدود','Authors and above (edit_published_posts)'=>'المؤلفون وما فوق (تحرير_نشر_المشاركات)','Contributors and above — default (edit_posts)'=>'المساهمون وما فوق — الافتراضي (تحرير_المشاركات)','Editors and above (edit_others_posts)'=>'المحررون وما فوق (تحرير_مشاركات_الآخرين)','Administrators only (manage_options)'=>'المسؤولون فقط (إدارة_الخيارات)','AI Limits & Security'=>'حدود و أمان الذكاء الاصطناعي','Cap how much AI usage the site can generate and restrict which user roles may trigger paid AI calls. Sits on top of the per-user rate limit (30 requests / minute, hardcoded) that already protects against single-user runaway loops.'=>'تحديد مقدار استخدام الذكاء الاصطناعي الذي يمكن للموقع توليده وتقييد الأدوار التي يمكنها تشغيل مكالمات الذكاء الاصطناعي المدفوعة. يتوضع فوق حد المعدل لكل مستخدم (30 طلبًا / دقيقة، مبرمج بشكل ثابت) الذي يحمي بالفعل من حلقات الجري غير المحدودة لمستخدم واحد.','Daily request limit'=>'حد الطلب اليومي','Site-wide ceiling on AI requests per UTC day (counts both Toolbar translations and block revisions). Counter resets at UTC midnight. Set to 0 to disable the cap.'=>'السقف على مستوى الموقع لطلبات الذكاء الاصطناعي لكل يوم بالتوقيت العالمي المنسق (يشمل ترجمات شريط الأدوات ومراجعات الكتل). يعاد تعيين العداد عند منتصف الليل بالتوقيت العالمي المنسق. اضبطه على 0 لتعطيل الحد.','Minimum role'=>'الدور الأدنى','Lowest WordPress capability allowed to trigger AI features. Tightening this on multi-author sites prevents Contributors or trial accounts from running paid AI calls. Override per-feature via the linguaforge_required_capability filter.'=>'أدنى قدرة في ووردبريس مسموح بها لتفعيل ميزات الذكاء الاصطناعي. تضييق هذا على مواقع متعددة المؤلفين يمنع المساهمين أو الحسابات التجريبية من تشغيل مكالمات الذكاء الاصطناعي المدفوعة. تجاوز حسب الميزة عبر مرشح `linguaforge_required_capability`.','Translation Limits'=>'حدود الترجمة','Control how much content is sent to the AI and how large the response can be. Leave a field blank to use the built-in default (shown as placeholder). Raise these values if large pages are being cut off; lower them to reduce API costs.'=>'تحكم في مقدار المحتوى المرسل إلى الذكاء الاصطناعي ومدى حجم الاستجابة الممكن. اترك حقلًا فارغًا لاستخدام الافتراضي المدمج (المعروض كمحدد موضع). قم برفع هذه القيم إذا كانت الصفحات الكبيرة تُقطع؛ وخفضها لتقليل تكاليف API.','Model tier'=>'طبقة النموذج','Quality (default — Sonnet / GPT-4o / Gemini Pro)'=>'الجودة (افتراضي — Sonnet / GPT-4o / Gemini Pro)','Light (fast and cost-effective — Haiku / Flash)'=>'خفيف (سريع وفعال من حيث التكلفة — Haiku / Flash)','Which model tier to use for full-page translation. Quality uses the model configured in the Models table above and is recommended for accurate, long-form translation. Switch to Light only if speed or cost is the priority and the content is short.'=>'أي طبقة نموذج لاستخدامها للترجمة الكاملة للصفحة. الجودة تستخدم النموذج المكون في جدول النماذج أعلاه ويوصى بها للترجمة الدقيقة والطويلة. انتقل إلى الخفيف فقط إذا كانت السرعة أو التكلفة أولوية والمحتوى قصير.','Max output tokens'=>'الحد الأقصى لعدد الرموز الناتجة','Maximum number of tokens the AI may produce in a single translation response. If a translation is silently cut off at the end, increase this value. Default: 16 000.'=>'الحد الأقصى لعدد الرموز التي يمكن للذكاء الاصطناعي إنتاجها في استجابة ترجمة واحدة. إذا تم قطع الترجمة بصمت في النهاية، قم بزيادة هذه القيمة. الافتراضي: 16000.','Max input characters'=>'عدد الأحرف المدخلة القصوى','Maximum number of characters of post content forwarded to the AI. 0 means no limit — the full content is always sent (recommended). Set a non-zero value only if your provider has a tight context window. A warning is written to the PHP error log whenever the content is trimmed.'=>'الحد الأقصى لعدد الأحرف لمحتوى المنشور الموجه إلى الذكاء الاصطناعي. 0 يعني عدم وجود حد — يتم دائمًا إرسال المحتوى الكامل (موصى به). اضبط قيمة غير صفرية فقط إذا كان مزود الخدمة الخاص بك لديه نافذة سياق ضيقة. يتم كتابة تحذير في سجل أخطاء PHP كلما تم تقليم المحتوى.','Quick Translation'=>'ترجمة سريعة','Quick Translation is used for snippet/chunk mode — short passages translated on demand from the toolbar, editor, or block popovers. It uses a separate, lighter configuration from the full-page translation to keep responses fast and cost-effective.'=>'تُستخدم الترجمة السريعة في وضع المقتطف / القطعة — ترجمات قصيرة يتم طلبها عند الحاجة من شريط الأدوات أو المحرر أو نوافذ النقر على الكتل. تستخدم تكوينًا منفصلًا وأخف من ترجمة الصفحة الكاملة للحفاظ على سرعة الاستجابة وتقليل التكاليف.','Light (default — fast and cost-effective)'=>'خفيف (افتراضي — سريع وفعال من حيث التكلفة)','Quality (Sonnet / GPT-4o / Gemini Pro)'=>'الجودة (سونيت / GPT-4o / جمنى برو)','The Light tier uses the fast model configured in the Models table above (default: Haiku / Flash). Switch to Quality if you need the same translation accuracy as full-page mode for snippets.'=>'يستخدم مستوى الضوء النموذج السريع المكون في جدول النماذج أعلاه (افتراضي: هايكو / فلاش). قم بالتبديل إلى الجودة إذا كنت بحاجة إلى نفس دقة الترجمة كوضع الصفحة الكاملة للمقتطفات.','Maximum tokens the AI may produce per quick translation. Default: 2 000.'=>'الحد الأقصى للرموز التي قد ينتجها الذكاء الاصطناعي لكل ترجمة سريعة. الافتراضي: 2000.','Maximum characters accepted from the input field. Default: 8 000.'=>'الحد الأقصى لعدد الأحرف المقبولة من حقل الإدخال. الافتراضي: 8000.','Content Generator'=>'مولد المحتوى','Controls the token budget and input limits for the AI Content Generator feature. Leave fields blank to use the built-in defaults.'=>'يتحكم في ميزانية الرموز وحدود الإدخال لميزة مولد محتوى الذكاء الاصطناعي. اترك الحقول فارغة لاستخدام الإعدادات الافتراضية المدمجة.','Maximum tokens the AI may produce per generation run. Raise this if full articles are being cut off. Default: 8 192.'=>'الحد الأقصى للرموز التي قد ينتجها الذكاء الاصطناعي لكل عملية توليد. زد هذا إذا تم قطع المقالات الكاملة. الافتراضي: 8192.','Max hints characters'=>'أقصى عدد أحرف للتلميحات','Maximum characters read from the Hints field. Default: 2 000.'=>'الحد الأقصى لعدد الأحرف المقروءة من حقل التلميحات. الافتراضي: 2000.','Max context characters'=>'أقصى عدد أحرف للسياق','Maximum characters of existing post content passed to the AI as seed context when no Hints are provided. Default: 6 000.'=>'الحد الأقصى لعدد الأحرف لمحتوى المنشور الموجود الممرر إلى الذكاء الاصطناعي كالسياق البذري عند عدم تقديم تلميحات. الافتراضي: 6000.','Maintenance'=>'الصيانة','Language Overrides'=>'تجاوزات اللغة','Upload compiled .mo files to override third-party plugin strings for specific locales — for example, a custom VikBooking translation that uses "apartment" instead of "room". Files must follow the WordPress naming convention: {textdomain}-{locale}.mo (e.g. vikbooking-ca.mo). They are stored in the uploads folder and survive plugin updates.'=>'قم بتحميل ملفات .mo المجمعة لتجاوز سلاسل الإضافات الخارجية للغات المحددة — على سبيل المثال، ترجمة VikBooking مخصصة تستخدم "شقة" بدلاً من "غرفة". يجب أن تتبع الملفات نمط تسمية ووردبريس: {textdomain}-{locale}.mo (مثال: vikbooking-ca.mo). يتم تخزينها في مجلد التحميلات وتظل بعد تحديث الإضافة.','Override file uploaded successfully.'=>'تم تحميل ملف التجاوز بنجاح.','Override file deleted.'=>'تم حذف ملف التجاوز.','No file was selected.'=>'لم يتم اختيار أي ملف.','Only .mo files are accepted.'=>'فقط ملفات .mo مقبولة.','The upload failed — please try again.'=>'فشل التحميل — يرجى المحاولة مرة أخرى.','Could not save the file. Check that the uploads folder is writable.'=>'تعذر حفظ الملف. تحقق من أن مجلد التحميلات قابل للكتابة.','Invalid filename.'=>'اسم ملف غير صالح.','Security check failed — file path is not permitted.'=>'فشل التحقق الأمني — مسار الملف غير مسموح به.','An unknown error occurred.'=>'حدث خطأ غير معروف.','Text domain / locale'=>'نطاق النص / اللغة','Files'=>'الملفات','Size'=>'الحجم','Delete all files for this override (both .mo and .po)?'=>'هل تريد حذف جميع الملفات لهذا التجاوز (ملفات .mo و .po)؟','No override files uploaded yet.'=>'لم يتم تحميل ملفات تجاوز بعد.','Upload .mo file'=>'تحميل ملف .mo','Accepts compiled .mo files only. Filename must follow the pattern {textdomain}-{locale}.mo. Uploading a file with the same name as an existing one will replace it.'=>'يقبل فقط ملفات .mo المجمعة. يجب أن يتبع اسم الملف النمط {textdomain}-{locale}.mo. استبدال ملف بنفس الاسم سيقوم بالاستبدال.','Upload Override'=>'تحميل التجاوز','Loco Translate — Copy to Safe Storage'=>'Loco Translate — النسخ إلى التخزين الآمن','Loco Translate stores its custom translations in wp-content/languages/loco/ — a location that can be silently wiped by a WP core update, plugin reinstall, or if Loco Translate itself is removed. Copying files here moves them into the Lingua Forge i18n-overrides directory, which persists through all of those events and is loaded automatically on every request.'=>'يخزن Loco Translate ترجماته المخصصة في wp-content/languages/loco/ — وهو موقع يمكن أن يتم مسحه بصمت بواسطة تحديث نواة ووردبريس، إعادة تثبيت الإضافة، أو إذا تمت إزالة Loco Translate نفسه. نسخ الملفات هنا ينقلها إلى دليل Lingua Forge i18n-overrides، الذي يستمر خلال جميع تلك الأحداث ويُحمّل تلقائيًا في كل طلب.','File copied to safe storage successfully.'=>'تم نسخ الملف إلى التخزين الآمن بنجاح.','Source file not found.'=>'لم يتم العثور على الملف المصدر.','Could not copy the file. Check that the uploads folder is writable.'=>'تعذر نسخ الملف. تحقق من أن مجلد التحميلات قابل للكتابة.','Invalid file reference.'=>'مرجع ملف غير صالح.','Type'=>'النوع','✓ In safe storage'=>'✓ في التخزين الآمن','Copy to safe storage'=>'نسخ إلى التخزين الآمن','No custom Loco Translate files found yet. They appear here once you save a translation in Loco Translate.'=>'لم يتم العثور على ملفات Loco Translate مخصصة بعد. تظهر هنا بمجرد حفظ ترجمة في Loco Translate.','AI Cache'=>'ذاكرة التخزين المؤقت للذكاء الاصطناعي','Lingua Forge caches AI-generated translations, meta descriptions, excerpts, and generated content per-post so unchanged inputs do not re-trigger a paid API call. Cached entries are automatically invalidated when their inputs change. Clear the cache manually to reclaim database space, force a resync after switching providers or editing prompt templates, or troubleshoot a cache-related issue.'=>'يخزن Lingua Forge ترجمات الذكاء الاصطناعي المولدة، والوصف التعريفي، والمقتطفات، والمحتوى المولد لكل منشور بحيث لا تعيد المدخلات غير المتغيرة تفعيل استدعاء API مدفوع. يتم إبطال صلاحية الإدخالات المخزنة تلقائيًا عند تغيير مدخلاتها. امسح الذاكرة المؤقتة يدويًا لاستعادة مساحة قاعدة البيانات، أو لإعادة مزامنة بعد تغيير المزودين أو تحرير قوالب الطلبات، أو لاستكشاف مشكلة تتعلق بالذاكرة المؤقتة.','AI cache cleared. %d entry was removed.'=>'تم مسح ذاكرة التخزين المؤقت للذكاء الاصطناعي. تم إزالة %d إدخال.' . "\0" . 'تم مسح ذاكرة التخزين المؤقت للذكاء الاصطناعي. تم إزالة %d إدخالات.' . "\0" . '' . "\0" . '' . "\0" . '' . "\0" . '','Clear all cached AI results? Future requests will trigger fresh API calls until the cache rebuilds.'=>'هل تريد مسح جميع نتائج الذكاء الاصطناعي المخزنة مؤقتًا؟ ستؤدي الطلبات المستقبلية إلى استدعاءات API جديدة حتى يتم إعادة بناء الذاكرة المؤقتة.','Clear AI Cache'=>'مسح ذاكرة التخزين المؤقت للذكاء الاصطناعي','Debug Files'=>'ملفات التصحيح','When debug logging is enabled (via the toggle below or by defining LINGUAFORGE_AI_DEBUG in wp-config.php), the Translation and FSE template translation features write their raw AI prompts and responses to disk for troubleshooting. Use this section to monitor that output and clear it once you have what you need — the files can grow quickly on large pages. Configure the destination directory via the linguaforge_debug_dir filter.'=>'عندما يتم تفعيل تسجيل التصحيح (عبر التبديل أدناه أو بتعريف LINGUAFORGE_AI_DEBUG في wp-config.php)، تكتب ميزات ترجمة القالب وترجمة الترجمة FSE مطالبات الذكاء الاصطناعي واستجاباتهما إلى القرص لأغراض استكشاف الأخطاء وإصلاحها. استخدم هذا القسم لمراقبة تلك المخرجات ومسحها بمجرد أن تحصل على ما تحتاجه — يمكن أن تنمو الملفات بسرعة على الصفحات الكبيرة. قم بتكوين دليل الوجهة عبر مرشح linguaforge_debug_dir.','Debug files cleared. %d file was removed.'=>'تم مسح ملفات التصحيح. تم حذف ملف واحد.' . "\0" . 'تم مسح ملفات التصحيح. تم حذف %d ملفات.' . "\0" . '' . "\0" . '' . "\0" . '' . "\0" . '','Debug logging enabled.'=>'تم تفعيل تسجيل التصحيح.','Debug logging disabled.'=>'تم تعطيل تسجيل التصحيح.','Debug logging'=>'تسجيل التصحيح','Write AI prompts and responses to disk for troubleshooting'=>'كتابة مطالبات واستجابات الذكاء الاصطناعي إلى القرص لأغراض استكشاف الأخطاء وإصلاحها','Forced ON by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'مُجبر على التشغيل من قبل الثابت LINGUAFORGE_AI_DEBUG في wp-config.php. احذف تلك السطر للتحكم في هذا التبديل من هنا.','Forced OFF by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'مُجبر على الإيقاف من قبل الثابت LINGUAFORGE_AI_DEBUG في wp-config.php. احذف تلك السطر للتحكم في هذا التبديل من هنا.','Files land in the directory below. Useful for diagnosing translation issues — turn off once you have what you need so the files do not accumulate. You can also force this from wp-config.php with `define( \'LINGUAFORGE_AI_DEBUG\', true );` which overrides the toggle.'=>'تصل الملفات إلى الدليل أدناه. مفيد لتشخيص مشكلات الترجمة — قم بإيقاف التشغيل بمجرد أن تحصل على ما تحتاجه حتى لا تتراكم الملفات. يمكنك أيضًا فرض ذلك من wp-config.php باستخدام `define( \'LINGUAFORGE_AI_DEBUG\', true );` الذي يتجاوز التبديل.','Currently:'=>'حاليًا:','✓ Enabled'=>'✓ مفعّل','✗ Disabled'=>'✗ معطل','Directory'=>'الدليل','Filter with linguaforge_debug_dir to redirect debug output to a non-public location.'=>'مرر مع linguaforge_debug_dir لإعادة توجيه مخرجات التصحيح إلى موقع غير عام.','.txt file(s) in the directory'=>'.txt ملف(ات) في الدليل','Save Debug Setting'=>'حفظ إعداد التصحيح','Delete all .txt files in the debug directory? The directory itself will remain so future debug writes still land cleanly.'=>'هل تريد حذف جميع ملفات .txt في دليل التصحيح؟ سيظل الدليل نفسه موجودًا حتى تستمر عمليات التصحيح المستقبلية في الوصول إليه بشكل نظيف.','Clear Debug Files'=>'مسح ملفات التصحيح','Per-block translation cache shared across posts. Configure on/off in Settings → Behavior. Stats below show what is currently cached; clearing forces every block to be re-translated on next request (useful after upgrading models or to recover database space).'=>'ذاكرة الترجمة المؤقتة مشتركة عبر الكتل. قم بتكوين التشغيل/الإيقاف في الإعدادات → السلوك. تظهر الإحصائيات أدناه ما هو مخزن حاليًا؛ يؤدي المسح إلى إعادة ترجمة كل كتلة في الطلب التالي (مفيد بعد ترقية النماذج أو لاستعادة مساحة قاعدة البيانات).','Translation Memory cleared. %d cached block was removed.'=>'تم مسح ذاكرة الترجمة المؤقتة. تم حذف كتلة مخزنة واحدة.' . "\0" . 'تم مسح ذاكرة الترجمة المؤقتة. تم حذف %d كتل مخزنة.' . "\0" . '' . "\0" . '' . "\0" . '' . "\0" . '','Status'=>'الحالة','— toggle in Settings → Behavior.'=>'— التبديل في الإعدادات → السلوك.','Cached blocks'=>'الكتل المخزنة مؤقتًا','Cumulative cache hits'=>'نقرات الكاش التراكمية','(avg %.1f hits/block)'=>'(متوسط %.1f نقرات/كتلة)','Oldest entry'=>'أقدم إدخال','Newest entry'=>'أحدث إدخال','Approximate size'=>'الحجم التقريبي','Clear the entire Translation Memory? Future translations will rebuild the cache as they run.'=>'هل تريد مسح ذاكرة الترجمة بالكامل؟ ستقوم الترجمات المستقبلية بإعادة بناء الكاش أثناء تشغيلها.','Clear Translation Memory'=>'مسح ذاكرة الترجمة','Uninstall Behaviour'=>'إلغاء تثبيت السلوك','Controls what happens when an administrator deletes the plugin from Plugins → Installed Plugins → Delete. Plugin settings and AI caches are always removed. Language assignments and translation relationships are kept by default so an accidental uninstall or a reinstall can pick up where it left off.'=>'يحدد ما يحدث عندما يقوم مسؤول بحذف الإضافة من الإضافات → الإضافات المثبتة → حذف. يتم دائمًا حذف إعدادات الإضافة وذاكرة التخزين المؤقت للذكاء الاصطناعي. يتم الاحتفاظ بتعيينات اللغة والعلاقات الترجمة بشكل افتراضي بحيث يمكن لمسح غير مقصود أو إعادة تثبيت أن يستأنف من حيث توقف.','Uninstall setting saved.'=>'تم حفظ إعداد إلغاء التثبيت.','Delete content data on uninstall'=>'حذف بيانات المحتوى عند إلغاء التثبيت','Also delete language assignments, translation relationships, meta descriptions, glossary, and Translation Memory when the plugin is uninstalled'=>'احذف أيضًا تعيينات اللغة، علاقات الترجمة، الأوصاف التعريفية، القاموس، وذاكرة الترجمة عند إلغاء تثبيت الإضافة.','Warning:'=>'تحذير:','If checked, uninstalling the plugin will permanently delete all language assignments, translation relationships, meta descriptions, per-page presets, the AI glossary, and Translation Memory for every post on this site. This cannot be undone. Leave unchecked unless you are fully removing multilingual support from the site.'=>'إذا تم تحديده، فإن إلغاء تثبيت الإضافة سيحذف بشكل دائم جميع تعيينات اللغة، علاقات الترجمة، الأوصاف التعريفية، الإعدادات المسبقة للصفحات، قاموس الذكاء الاصطناعي، وذاكرة الترجمة لكل منشور على هذا الموقع. لا يمكن التراجع عن ذلك. اتركه غير محدد إلا إذا كنت تزيل دعم التعددية اللغوية من الموقع بالكامل.','Save Uninstall Setting'=>'حفظ إعداد إلغاء التثبيت','Router'=>'الموجه','Primary language saved.'=>'تم حفظ اللغة الأساسية.','Permalink rules flushed successfully.'=>'تم تفريغ قواعد الرابط الدائم بنجاح.','Primary Language'=>'اللغة الأساسية','The primary language is always served at the root of your site — no URL prefix in path mode, no language subdomain in subdomain mode. All other languages use either a /lang/ path prefix (e.g. example.com/de/) or a language subdomain (e.g. de.example.com), depending on the URL structure setting below.'=>'اللغة الأساسية دائمًا تُقدم في جذر موقعك — بدون بادئة URL في وضع المسار، بدون نطاق فرعي للغة في وضع النطاق الفرعي. تستخدم جميع اللغات الأخرى بادئة مسار /lang/ (مثل example.com/de/) أو نطاق فرعي للغة (مثل de.example.com)، اعتمادًا على إعداد بنية URL أدناه.','Primary language'=>'اللغة الأساسية','After changing the primary language, flush permalinks (section below) for the URL routing to update.'=>'بعد تغيير اللغة الأساسية، قم بتفريغ الروابط الدائمة (القسم أدناه) لتحديث توجيه URL.','URL structure'=>'بنية URL','Path prefix — example.com/de/'=>'بادئة المسار — example.com/de/','Subdomain — de.example.com/'=>'النطاق الفرعي — de.example.com/','Subdomain mode requires your web server to point all language subdomains (e.g. de.example.com) to this WordPress installation. After switching modes, flush permalink rules and clear any caches. If your home URL includes www (e.g. www.example.com), use the lf_base_domain filter to set the bare apex domain so subdomains are constructed correctly.'=>'يتطلب وضع النطاق الفرعي أن يشير خادم الويب الخاص بك إلى جميع النطاقات الفرعية للغة (مثل de.example.com) إلى تثبيت ووردبريس هذا. بعد تغيير الأوضاع، قم بمسح قواعد الروابط الثابتة وامسح أي ذاكرات مؤقتة. إذا كان عنوان URL الرئيسي الخاص بك يتضمن www (مثل www.example.com)، استخدم مرشح lf_base_domain لضبط النطاق الأساسي الخالي بحيث يتم إنشاء النطاقات الفرعية بشكل صحيح.','Browser language redirect'=>'إعادة توجيه لغة المتصفح','Redirect visitors to their preferred language based on the browser\'s Accept-Language header'=>'إعادة توجيه الزوار إلى لغتهم المفضلة استنادًا إلى رأس Accept-Language الخاص بالمتصفح','When enabled, first-time visitors with no language cookie and no language prefix in the URL are redirected to the closest matching language version. The redirect is skipped if the browser\'s preferred language is not among the active router languages. Once a visitor selects a language via the switcher, the cookie takes priority and the browser header is ignored on all future visits.'=>'عند التمكين، يتم إعادة توجيه الزائرين لأول مرة الذين لا يملكون كوكي لغة ولا يوجد بادئة لغة في عنوان URL إلى أقرب إصدار مطابق للغة. يتم تخطي إعادة التوجيه إذا لم تكن اللغة المفضلة للمتصفح من بين لغات الموجه النشطة. بمجرد أن يختار الزائر لغة عبر المبدل، تأخذ الكوكي الأولوية ويتم تجاهل رأس المتصفح في جميع الزيارات المستقبلية.','Save Router Settings'=>'حفظ إعدادات الموجه','Flush Permalinks'=>'مسح الروابط الثابتة','Regenerates WordPress rewrite rules so URL prefixes, language-specific slugs, and archive rewrites are all in sync. Necessary after changing the primary language or adding new language support.'=>'يعيد إنشاء قواعد إعادة كتابة ووردبريس بحيث تكون بادئات URL، والكلمات المفتاحية الخاصة باللغة، وإعادة كتابة الأرشيف متزامنة. ضروري بعد تغيير اللغة الأساسية أو إضافة دعم لغة جديدة.','Flush Permalink Rules'=>'مسح قواعد الرابط الثابت','Active Languages'=>'اللغات النشطة','Languages currently known to the router (derived from installed WordPress locale packs plus the primary language). Install additional language packs in the section below to make more languages available for routing and translation.'=>'اللغات المعروفة حاليًا للموجه (مشتقة من حزم اللغة المثبتة في ووردبريس بالإضافة إلى اللغة الأساسية). قم بتثبيت حزم لغوية إضافية في القسم أدناه لجعل المزيد من اللغات متاحة للتوجيه والترجمة.','%d locale pack installed.'=>'تم تثبيت حزمة لغة واحدة (%d).' . "\0" . 'تم تثبيت حزم لغوية (%d).' . "\0" . '' . "\0" . '' . "\0" . '' . "\0" . '','Install a Language'=>'تثبيت لغة','Download and install a WordPress core language pack directly from WordPress.org. Once installed, the locale becomes available for URL routing and the AI translation workflow. The list of available languages is fetched on demand — click the button below to load it.'=>'قم بتنزيل وتثبيت حزمة لغة ووردبريس الأساسية مباشرة من WordPress.org. بمجرد التثبيت، تصبح اللغة متاحة لتوجيه URL وسير عمل الترجمة بالذكاء الاصطناعي. يتم جلب قائمة اللغات المتاحة عند الطلب — انقر على الزر أدناه لتحميلها.','Language installation is disabled on this server. The DISALLOW_FILE_MODS constant is set in wp-config.php. Install language packs manually via WP-CLI: wp language core install de_DE'=>'تم تعطيل تثبيت اللغة على هذا الخادم. تم تعيين الثابت DISALLOW_FILE_MODS في wp-config.php. قم بتثبيت حزم اللغات يدويًا عبر WP-CLI: wp language core install de_DE','Load available languages'=>'تحميل اللغات المتاحة','— select a language —'=>'— اختر لغة —','Install'=>'تثبيت','Language Setup'=>'إعداد اللغة','No secondary languages configured. Install a language pack above to enable template scaffolding.'=>'لم يتم تكوين لغات ثانوية. قم بتثبيت حزمة لغة أعلاه لتمكين إنشاء القوالب.','Select a language to manage its FSE templates, template parts, and navigation menus.'=>'اختر لغة لإدارة قوالب FSE الخاصة بها، وأجزاء القالب، وقوائم التنقل.','Forbidden'=>'ممنوع','Language installation is disabled on this server (DISALLOW_FILE_MODS is set).'=>'تم تعطيل تثبيت اللغة على هذا الخادم (تم تعيين DISALLOW_FILE_MODS).','Invalid locale code.'=>'رمز اللغة غير صالح.','Language %s installed successfully.'=>'تم تثبيت لغة %s بنجاح.','Language pack installation failed. The language may already be installed, the locale code may be incorrect, or your server may block file writes.'=>'فشل تثبيت حزمة اللغة. قد تكون اللغة مثبتة بالفعل، أو قد يكون رمز اللغة غير صحيح، أو قد يمنع الخادم كتابة الملفات.','Navigations'=>'التنقلات','Navigation translation requires an active AI provider. Configure an API key in the API Keys tab.'=>'يتطلب ترجمة التنقل وجود مزود ذكاء اصطناعي نشط. قم بتكوين مفتاح API في علامة تبويب مفاتيح API.','Navigation'=>'التنقل','Action'=>'إجراء','Re-translate'=>'إعادة الترجمة','CPT Block Patterns'=>'أنماط كتل CPT','Block patterns registered for custom post types. Use the Translate button to produce a language variant. The translated content is saved here and can be copied into any CPT post from the block editor Pattern inserter or used as a starting point for a Synced Pattern (Reusable Block).'=>'أنماط الكتل المسجلة لأنواع المنشورات المخصصة. استخدم زر الترجمة لإنتاج نسخة بلغة أخرى. يتم حفظ المحتوى المترجم هنا ويمكن نسخه إلى أي منشور CPT من أداة إدراج الأنماط في محرر الكتل أو استخدامه كنقطة انطلاق لنمط متزامن (كتلة قابلة لإعادة الاستخدام).','Pattern'=>'نمط','Post Types'=>'أنواع المنشورات','✓ Translation saved'=>'✓ تم حفظ الترجمة','View'=>'عرض','Template Parts'=>'أجزاء القالب','Language-specific copies of the theme\'s template parts. Once scaffolded, templates are updated to reference the language-specific part.'=>'نسخ خاصة باللغة من أجزاء قالب السمة. بمجرد إنشائها، يتم تحديث القوالب للإشارة إلى الجزء الخاص باللغة.','Part'=>'جزء','Status / Actions'=>'الحالة / الإجراءات','Fix Links'=>'تصحيح الروابط','Fix Nav'=>'تصحيح التنقل','Create'=>'إنشاء','Templates'=>'القوالب','FSE templates seeded from the active theme. Create then customise in the Site Editor.'=>'تم زرع قوالب FSE من السمة النشطة. أنشئها ثم قم بتخصيصها في محرر الموقع.','Actions'=>'إجراءات','Fix Parts'=>'تصحيح الأجزاء','Create missing'=>'إنشاء مفقود','Translate all'=>'ترجمة الكل','Fix all parts'=>'تصحيح جميع الأجزاء','Fix all links'=>'تصحيح جميع الروابط','Anthropic (Claude)'=>'أنثروبيك (كلود)','OpenAI (GPT)'=>'OpenAI (GPT)','Google (Gemini)'=>'جوجل (جميني)','Testing…'=>'جارٍ الاختبار…','✓ Connection OK'=>'✓ الاتصال جيد','✗ Failed:'=>'✗ فشل:','No response from provider — check the error log for details.'=>'لا استجابة من المزود — تحقق من سجل الأخطاء للتفاصيل.','Network error — could not reach the WordPress AJAX endpoint.'=>'خطأ في الشبكة — تعذر الوصول إلى نقطة نهاية WordPress AJAX.','Loading…'=>'جارٍ التحميل…','Installing…'=>'جارٍ التثبيت…','✓ Language installed.'=>'✓ تم تثبيت اللغة.','✗ Error:'=>'✗ خطأ:','Creating…'=>'جارٍ الإنشاء…','✓ All templates created.'=>'✓ تم إنشاء جميع القوالب.','Some templates could not be created.'=>'تعذر إنشاء بعض القوالب.','✓ All parts created.'=>'✓ تم إنشاء جميع الأجزاء.','Some parts could not be created.'=>'تعذر إنشاء بعض الأجزاء.','✓ All translated.'=>'✓ تم الترجمة جميعها.','Some translations failed.'=>'فشلت بعض الترجمات.','Review carefully — links and slugs not updated.'=>'راجع بعناية — لم يتم تحديث الروابط والروابط المختصرة.','Fixing…'=>'جارٍ الإصلاح…','✓ Links fixed.'=>'✓ تم إصلاح الروابط.','Some link fixes failed.'=>'فشلت بعض إصلاحات الروابط.','✓ Parts fixed.'=>'✓ تم إصلاح الأجزاء.','Some part fixes failed.'=>'فشلت بعض إصلاحات الأجزاء.','✓ Nav refs fixed.'=>'✓ تم إصلاح مراجع التنقل.','Some nav ref fixes failed.'=>'فشلت بعض إصلاحات مراجع التنقل.','✓ Pattern translated.'=>'✓ تم ترجمة النمط.','Pattern translation failed.'=>'فشلت ترجمة النمط.','Hide'=>'إخفاء','Built-in preset instructions:'=>'تعليمات الإعداد المسبق المدمجة:','No built-in instructions — each AI feature uses its own tuned defaults. Fill in the Custom prompt instructions field below to add your own site-wide rules.'=>'لا توجد تعليمات مدمجة — كل ميزة AI تستخدم إعداداتها الافتراضية الخاصة. املأ حقل تعليمات المطالب المخصصة أدناه لإضافة قواعد موقعك الخاصة.','Settings'=>'الإعدادات','You do not have permission to manage these settings.'=>'ليس لديك إذن لإدارة هذه الإعدادات.','Lingua Forge — Settings'=>'لينغا فورج — الإعدادات','Settings saved.'=>'تم حفظ الإعدادات.','Save Settings'=>'حفظ الإعدادات','Standard'=>'افتراضي','Technical / Scientific'=>'تقني / علمي','Legal / Compliance'=>'قانوني / امتثال','Creative / Marketing'=>'إبداعي / تسويقي','Full Article'=>'المقال الكامل','Introduction only'=>'مقدمة فقط','Structured Outline'=>'مخطط منظم','Generate Content'=>'إنشاء المحتوى','Hints'=>'تلميحات','Key points, ideas, or structure to build from…'=>'نقاط رئيسية، أفكار، أو هيكل للبناء عليه…','Tone'=>'نغمة','Output'=>'مخرجات','Generate Excerpt'=>'إنشاء مقتطف','Generate Meta Description'=>'إنشاء وصف ميتا','Translate Content'=>'ترجمة المحتوى','Mode'=>'الوضع','Full post'=>'المقال كامل','Translate chunk'=>'ترجمة الجزء','Target Language'=>'اللغة المستهدفة','Text to translate'=>'النص المراد ترجمته','Paste a footnote, sentence, or any snippet here…'=>'الصق حاشية، جملة، أو أي مقتطف هنا…','Also generate meta description'=>'أيضًا إنشاء وصف ميتا','Translated Names'=>'الأسماء المترجمة','Name displayed in this language. Leave empty to use the source name.'=>'الاسم المعروض بهذه اللغة. اتركه فارغًا لاستخدام الاسم المصدر.','Too many AI requests. Please retry in %d seconds.'=>'طلبات الذكاء الاصطناعي كثيرة جدًا. يرجى المحاولة مرة أخرى بعد %d ثوانٍ.','Daily AI quota reached (%1$d requests). Resets at %2$s UTC.'=>'تم الوصول إلى الحصة اليومية للذكاء الاصطناعي (%1$d طلبات). تتجدد في %2$s بالتوقيت العالمي المنسق.','View Lingua Forge details'=>'عرض تفاصيل لينغا فورج','View details'=>'عرض التفاصيل','Visit plugin site'=>'زيارة موقع الإضافة','%d language not yet linked'=>'لم يتم ربط %d لغة بعد' . "\0" . 'لم يتم ربط %d لغات بعد' . "\0" . '' . "\0" . '' . "\0" . '' . "\0" . '','This is the source page. Footnotes are edited directly in the block editor.'=>'هذه هي صفحة المصدر. يتم تحرير الحواشي مباشرة في محرر الكتل.','No source page linked yet.'=>'لم يتم ربط صفحة المصدر بعد.','The source page has no footnotes.'=>'صفحة المصدر لا تحتوي على حواشي.','These footnotes come from the source page and are shown here for reference only. Add them to this page using the block editor.'=>'هذه الحواشي تأتي من صفحة المصدر وتعرض هنا للمرجعية فقط. أضفها إلى هذه الصفحة باستخدام محرر الكتل.','<strong>Lingua Forge:</strong> %1$d localized template(s) from the &#8220;%2$s&#8221; theme are preserved in the database but are currently inactive. They will become active again if you reactivate that theme. To carry your translations to the new theme, regenerate them via <strong>Settings → Lingua Forge → Router → FSE scaffold</strong>.'=>'<strong>لينغوا فورج:</strong> تم الاحتفاظ بـ %1$d قالبًا مترجمًا من سمة &#8220;%2$s&#8221; في قاعدة البيانات ولكنه غير نشط حاليًا. ستصبح نشطة مرة أخرى إذا قمت بإعادة تفعيل تلك السمة. لنقل ترجماتك إلى السمة الجديدة، أعد إنشائها عبر <strong>الإعدادات → لينغوا فورج → التوجيه → هيكل FSE</strong>.','Scanning posts for broken language links…'=>'فحص المنشورات للروابط المكسورة…','Re-scanning…'=>'إعادة الفحص…','Scan failed: '=>'فشل الفحص: ','unknown error'=>'خطأ غير معروف','Scan request failed. Please try again.'=>'فشل طلب الفحص. يرجى المحاولة مرة أخرى.','⚠ No <strong>{lang}</strong> posts found. Make sure all translated posts have their Language meta set to <strong>{lang}</strong> in the Language metabox.'=>'⚠ لم يتم العثور على منشورات <strong>{lang}</strong>. تأكد من أن جميع المنشورات المترجمة تحتوي على متغير اللغة مضبوط على <strong>{lang}</strong> في مربع بيانات اللغة.','✅ No broken links or template mismatches found for <strong>{lang}</strong>. Scanned <strong>{scanned}</strong> post(s) and page(s) — all checks passed. Template part links (header, footer, sidebar) are not included here — use the Fix Template Parts button to check those separately.'=>'✅ لم يتم العثور على روابط مكسورة أو تطابقات قالب خاطئة لـ <strong>{lang}</strong>. تم فحص <strong>{scanned}</strong> منشورًا و صفحة — جميع الفحوصات ناجحة. روابط أجزاء القالب (رأس الصفحة، تذييل الصفحة، الشريط الجانبي) غير مشمولة هنا — استخدم زر إصلاح أجزاء القالب لفحصها بشكل منفصل.','<strong>{n}</strong> auto-fixable link(s)'=>'<strong>{n}</strong> رابط قابل للإصلاح التلقائي','<strong>{n}</strong> link(s) needing manual review'=>'<strong>{n}</strong> روابط بحاجة لمراجعة يدوية','and'=>'و','Found {parts} across <strong>{total}</strong> of <strong>{scanned}</strong> scanned post(s) for <strong>{lang}</strong>.'=>'تم العثور على {parts} عبر <strong>{total}</strong> من منشورات و صفحات <strong>{scanned}</strong> التي تم فحصها للغة <strong>{lang}</strong>.','Post'=>'منشور','Links'=>'روابط','link(s)'=>'رابط(روابط)','Fix'=>'إصلاح','✅ Fixed ({n})'=>'✅ تم الإصلاح ({n})','⚠ No changes — re-scan?'=>'⚠ لا تغييرات — إعادة الفحص؟','⚠ No changes'=>'⚠ لا تغييرات','❌ Failed'=>'❌ فشل','Done — {done} of {total} post(s